full=Path('tools/assets/Layout102.cs.txt').read_text(encoding='utf-8-sig');prefix=full.split(' public static string Run()')[0].replace('class Layout102','class Polish102')
code=prefix+r''' public static string Run(){var s=UnityEngine.SceneManagement.SceneManager.GetActiveScene();var root=GameObject.Find("Lobby_Island_Visual_Prototype").transform;var main=root.Find("01_Central_Island");var weapon=main.Find("02_Open_Market/03_Guns_Source_Home_GunsStore");var roof=weapon.Cast<Transform>().Where(t=>t.name=="Striped_Canvas").OrderBy(t=>t.localPosition.z).ThenBy(t=>t.localPosition.x).ToArray();for(int i=0;i<roof.Length;i++){var t=roof[i];var p=t.localPosition;p.z=1.15f+(i/2+.5f)*2.35f/8;t.localPosition=p;var size=t.localScale;size.z=2.35f/8-.015f;t.localScale=size;}foreach(var t in weapon.Cast<Transform>().Where(t=>t.name=="Canopy_Pole"&&t.localPosition.z<0)){var p=t.localPosition;p.z=1.35f;t.localPosition=p;}foreach(string name in new[]{"Canvas_Front_Valance","Service_Sign","Sign_Text"}){var t=weapon.Find(name);var p=t.localPosition;p.z=name=="Canvas_Front_Valance"?1.15f:name=="Service_Sign"?1.02f:.93f;t.localPosition=p;}var supply=main.Find("02_Open_Market/02_General_Source_Home_GeneralStore");Fit(supply.Find("Static_Staff_Supplies_Merchant102"),supply,new Vector3(1.15f,.18f,-.1f),0);var lab=main.Find("Animal_Laboratory097");Fit(lab.Find("Static_Staff_Lab_Technician102"),lab,new Vector3(.8f,.205f,4.02f),0);File.AppendAllText("Docs/assets/lobby-island/LAYOUT_STAFF102_VALIDATION.txt","\nFinal: armory canopy shortened to rear2.35m depth; sign retained over rear counter so front/side6bays unobstructed. Supplies/lab staff offset into visible gaps between products/reagents.\n");Shot(weapon.position+new Vector3(9,8,-13),weapon.position+Vector3.up*1.2f,9,"46-open-armory102");Shot(main.TransformPoint(new Vector3(0,5,-32)),main.TransformPoint(new Vector3(0,1,5)),28,"50-five-market-staff102");var bank=main.Find("Bank_Crystal_Boutique095");Shot(bank.position+new Vector3(7,3.2f,-11),bank.position+new Vector3(0,1.3f,0),8,"51-bank-clerk102");Shot(lab.position+new Vector3(8,8,-11),lab.position+Vector3.up*1.5f,8,"52-lab-technician102");EditorSceneManager.MarkSceneDirty(s);if(!EditorSceneManager.SaveScene(s))throw new Exception("Save failed");return "Saved open armory canopy and visibly offset staff, final staff photos recorded.";}
}'''
